// Appends Nail Care ids 251-300
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const T=`"Nail Care"`, Tes=`"Cuidado de Uñas"`, PT=`"Nail Care"`, PTes=`"Cuidado de Uñas"`
function fmt(q) {
  return `  { id: ${q.id}, topic: ${T}, topic_es: ${Tes}, psi_topic: ${PT}, psi_topic_es: ${PTes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const Q = [
  { id: 251, question: "The monomer and polymer components of a traditional (liquid-and-powder) acrylic nail system work by:", question_es: "Los componentes de monómero y polímero de un sistema de uñas acrílicas tradicional (líquido y polvo) funcionan:", options: ["The liquid monomer (typically EMA — ethyl methacrylate) initiates a polymerization reaction when mixed with the polymer powder — creating an acrylic bead that can be shaped and then hardens through chemical cross-linking without needing UV/LED light", "The powder dissolves the liquid to create a nail paint that is brushed onto the nail", "The monomer provides the color and the polymer provides the structure — they function separately, not as a combined system", "The polymer dissolves in acetone to remove existing enhancements while the monomer is used for application"], options_es: ["El monómero líquido (típicamente EMA — metacrilato de etilo) inicia una reacción de polimerización cuando se mezcla con el polvo de polímero — creando una bola de acrílico que se puede moldear y luego se endurece a través del entrecruzamiento químico sin necesidad de luz UV/LED", "El polvo disuelve el líquido para crear una pintura de uñas que se aplica con un pincel en la uña", "El monómero proporciona el color y el polímero proporciona la estructura — funcionan por separado, no como un sistema combinado", "El polímero se disuelve en acetona para eliminar las mejoras existentes mientras que el monómero se usa para la aplicación"], correct: 0, explanation: "In liquid-and-powder acrylic systems: the liquid is a monomer (EMA — ethyl methacrylate, the safe standard; or historically MMA — methyl methacrylate, now banned/restricted in many states). The powder contains polymer (pre-polymerized acrylic), pigments, and an initiator (benzoyl peroxide). When combined, they polymerize through free-radical chain reaction that generates heat (exotherm) as it sets." },
  { id: 252, question: "Methyl methacrylate (MMA) monomer is discouraged or banned in many states for nail use because:", question_es: "El metacrilato de metilo (MMA) monómero está desaconsejado o prohibido en muchos estados para uso en uñas porque:", options: ["MMA creates enhancements that adhere excessively strongly — they do not break away when the nail is impacted, instead tearing the natural nail plate with them; MMA is also associated with respiratory sensitization, allergic reactions, and nail damage significantly worse than EMA products", "MMA is more expensive than EMA and therefore cost-prohibitive for professional use", "MMA dries too slowly for practical professional nail service use", "MMA has a blue tint that discolors natural nails — this cosmetic issue is the primary reason for restrictions"], options_es: ["El MMA crea mejoras que se adhieren excesivamente fuerte — no se desprenden cuando la uña recibe un impacto, sino que arrancan la placa ungueal natural con ellas; el MMA también está asociado con la sensibilización respiratoria, las reacciones alérgicas y el daño ungueal significativamente peor que los productos de EMA", "El MMA es más caro que el EMA y por lo tanto es costoso para el uso profesional", "El MMA se seca demasiado lento para el uso profesional práctico de servicios de uñas", "El MMA tiene un tinte azul que decolora las uñas naturales — este problema cosmético es la razón principal de las restricciones"], correct: 0, explanation: "MMA (methyl methacrylate) monomer problems: (1) extremely hard — resists filing and requires very coarse abrasion, (2) bonds so strongly that traumatic separation tears the nail plate rather than breaking the enhancement, (3) causes contact sensitization (allergy), (4) poor odor (very strong fumes). EMA (ethyl methacrylate) is the professional standard — softer, appropriately adhesive, and safer." },
  { id: 253, question: "Proper consistency of an acrylic nail bead (the mixed acrylic picked up on the brush) is described as:", question_es: "La consistencia adecuada de una bola de acrílico de uña (el acrílico mezclado recogido en el pincel) se describe como:", options: ["A medium-wet bead that is workable for 30–60 seconds — too wet (excess monomer) means the acrylic will be over-flexible and porous (air bubbles); too dry means it sets too quickly and becomes grainy and unworkable before shaping is complete", "As dry as possible — dry beads create the hardest and most durable enhancements", "As wet as possible — wet beads have the best adhesion and are easiest to shape", "The consistency is irrelevant — all acrylic bead consistencies produce identical results after curing"], options_es: ["Una bola de humedad media que se puede trabajar durante 30–60 segundos — demasiado húmeda (exceso de monómero) significa que el acrílico será demasiado flexible y poroso (burbujas de aire); demasiado seca significa que se endurece demasiado rápido y se vuelve granulosa e inmanejable antes de que se complete el modelado", "Lo más seca posible — las bolas secas crean las mejoras más duras y duraderas", "Lo más húmeda posible — las bolas húmedas tienen la mejor adherencia y son más fáciles de moldear", "La consistencia es irrelevante — todas las consistencias de bolas de acrílico producen resultados idénticos después del curado"], correct: 0, explanation: "Acrylic bead consistency is critical to product quality. A medium consistency bead has about equal parts liquid and powder — it flows slightly and self-levels, providing workability without being over-liquid. Too wet (more monomer): over-reactive, porous, weak enhancement with increased allergy risk from excess monomer. Too dry (more powder): sets before shaping is complete, lumpy, brittle." },
  { id: 254, question: "An 'inhibition layer' in UV/LED gel nail products refers to:", question_es: "Una 'capa de inhibición' en los productos de gel de uñas UV/LED se refiere a:", options: ["A tacky, uncured layer on the surface of a cured gel coat — it results from oxygen in the air inhibiting the polymerization reaction at the gel's surface; it must be wiped off with a lint-free pad and cleanser before proceeding to the next coat or finishing step", "A protective film that is peeled off the gel before it is cured under the lamp", "The primer coat applied before gel application to inhibit lifting", "An allergic skin reaction to UV gel products requiring product removal"], options_es: ["Una capa pegajosa y sin curar en la superficie de una capa de gel curada — resulta del oxígeno en el aire que inhibe la reacción de polimerización en la superficie del gel; debe limpiarse con una almohadilla sin pelusa y limpiador antes de proceder a la siguiente capa o paso de acabado", "Una película protectora que se pela del gel antes de que se cure bajo la lámpara", "La capa de imprimante aplicada antes de la aplicación del gel para inhibir el levantamiento", "Una reacción alérgica de la piel a los productos de gel UV que requiere la remoción del producto"], correct: 0, explanation: "When gel cures under UV/LED light, atmospheric oxygen at the surface interferes with photoinitiator activation, leaving a sticky uncured residue — the inhibition (or tacky) layer. This must be removed by wiping with a lint-free cleanser pad before applying the next product layer or finishing the service. Failure to remove it leaves a cloudy, tacky finish." },
  { id: 255, question: "LED lamps for gel nail curing differ from UV lamps in that:", question_es: "Las lámparas LED para curado de gel de uñas difieren de las lámparas UV en que:", options: ["LED lamps emit specific narrow wavelengths that match the photoinitiators in compatible gel products — they cure faster (30–60 seconds vs 2–3 minutes for UV), consume less energy, and the bulbs last longer; however, not all gel products are compatible with LED lamps", "LED lamps are identical in output to UV lamps — the choice is purely aesthetic", "LED lamps require twice as long to cure gel as UV lamps, but produce harder gels", "LED lamps cannot cure gel nail products — they are only used for decorative purposes at the manicure station"], options_es: ["Las lámparas LED emiten longitudes de onda específicas y estrechas que coinciden con los fotoiniciadores en los productos de gel compatibles — curan más rápido (30–60 segundos vs 2–3 minutos para UV), consumen menos energía y las bombillas duran más; sin embargo, no todos los productos de gel son compatibles con las lámparas LED", "Las lámparas LED son idénticas en producción a las lámparas UV — la elección es puramente estética", "Las lámparas LED requieren el doble de tiempo para curar el gel que las lámparas UV, pero producen geles más duros", "Las lámparas LED no pueden curar productos de gel de uñas — solo se usan con fines decorativos en la estación de manicura"], correct: 0, explanation: "UV lamps emit broad-spectrum UV light (320–400nm); LED lamps emit narrow-spectrum light targeting specific nm wavelengths. LED advantages: faster curing (30–60s vs 2min UV), longer bulb life (50,000+ hours vs hundreds for UV), energy efficient. Important: only LED-compatible gel products (formulated with photoinitiators responsive to LED wavelengths) cure properly under LED. Check product compatibility." },
  { id: 256, question: "A pedicure tub or basin used in an esthetics establishment must be:", question_es: "Una tina o cubeta de pedicura usada en un establecimiento de estética debe ser:", options: ["Thoroughly cleaned and disinfected between each client using an EPA-registered disinfectant approved for use on the specific basin type — the disinfectant must be left in contact for the full required time; many state regulations have specific protocols for spa pedicure basins with internal jets", "Rinsed with hot water between clients — soap is only needed for weekly cleaning", "Cleaned once at the beginning and once at the end of each workday — between-client cleaning is not required for pedicure basins", "Replaced with a disposable liner that clients sit in — the basin itself requires no disinfection"], options_es: ["Limpiada y desinfectada a fondo entre cada cliente usando un desinfectante registrado por la EPA aprobado para su uso en el tipo de cubeta específico — el desinfectante debe dejarse en contacto durante el tiempo completo requerido; muchas regulaciones estatales tienen protocolos específicos para las cubetas de pedicura de spa con chorros internos", "Enjuagada con agua caliente entre clientes — el jabón solo se necesita para la limpieza semanal", "Limpiada una vez al comienzo y una vez al final de cada día de trabajo — la limpieza entre clientes no es requerida para las cubetas de pedicura", "Reemplazada con un forro desechable en el que se sientan los clientes — la cubeta en sí no requiere desinfección"], correct: 0, explanation: "Pedicure basins that contact client feet (broken or intact skin) require complete disinfection between clients. For footbaths/basins with jets (spa tubs): must be cleaned, flushed with disinfectant, and allowed full contact time. Many state regulations have specific detailed protocols for jetted pedicure tubs due to their complex internal plumbing that can harbor biofilm." },
  { id: 257, question: "The correct technique for trimming toenails during a pedicure service is:", question_es: "La técnica correcta para cortar las uñas de los pies durante un servicio de pedicura es:", options: ["Cut straight across — following the natural shape of the toe — rather than rounding the corners; cutting toenails in a curved shape (rounded into the corners) encourages ingrown nail development by directing nail growth into the lateral nail fold", "Cut in a rounded shape to follow the curve of the toe for aesthetic purposes", "Cut toenails at a 45-degree angle on both sides to prevent them from catching on socks", "Avoid cutting toenails entirely — filing is the only safe toenail length reduction technique"], options_es: ["Cortar en línea recta — siguiendo la forma natural del dedo del pie — en lugar de redondear las esquinas; cortar las uñas de los pies en forma curvada (redondeada hacia las esquinas) fomenta el desarrollo de uñas encarnadas al dirigir el crecimiento de la uña hacia el pliegue ungueal lateral", "Cortar en forma redondeada para seguir la curva del dedo del pie con fines estéticos", "Cortar las uñas de los pies en un ángulo de 45 grados en ambos lados para evitar que se enganchen en los calcetines", "Evitar cortar las uñas de los pies por completo — el limado es la única técnica segura de reducción de longitud de uñas de pies"], correct: 0, explanation: "Toenails should be trimmed straight across (parallel to the nail's proximal edge). Rounding the lateral corners leaves a spike of nail that can grow into the soft tissue of the lateral nail fold — causing a painful ingrown toenail. After straight trimming, the corners can be gently smoothed with a fine file, but the corners must not be cut below the tip of the toe." },
  { id: 258, question: "An ingrown toenail (onychocryptosis) observed during a pedicure service requires:", question_es: "Una uña encarnada del dedo del pie (onicriptosis) observada durante un servicio de pedicura requiere:", options: ["Referral to a physician or podiatrist if the nail is embedded in the flesh, causing pain, or showing signs of infection — minor early-stage ingrown nails may be gently smoothed at the free edge, but estheticians should not attempt to 'dig out' deeply embedded nail edges, which is a medical procedure", "Aggressive filing to remove the embedded nail edge in a single session to provide immediate client relief", "Applying antifungal cream and polish to cover the area for cosmetic improvement", "No service modification — pedicure services always proceed normally regardless of nail condition"], options_es: ["Derivación a un médico o podólogo si la uña está incrustada en la carne, causa dolor o muestra signos de infección — las uñas encarnadas menores en etapa inicial pueden alisarse suavemente en el borde libre, pero los esteticistas no deben intentar 'sacar' los bordes de uñas profundamente incrustados, lo cual es un procedimiento médico", "Limado agresivo para eliminar el borde de la uña incrustado en una sola sesión para proporcionar alivio inmediato al cliente", "Aplicar crema antimicótica y esmalte para cubrir el área para mejorar cosméticamente", "Sin modificación del servicio — los servicios de pedicura siempre proceden normalmente independientemente de la condición de las uñas"], correct: 0, explanation: "Ingrown toenails (especially those embedded in tissue, inflamed, or infected) are medical conditions outside esthetics scope of practice. Attempting to remove an embedded nail edge risks: worsening the injury, introducing infection, and causing significant pain. Estheticians may gently file a very minor rough edge, but should refer any significant ingrown nail condition to a physician or podiatrist." },
  { id: 259, question: "A callus on the foot is:", question_es: "Un callo en el pie es:", options: ["A diffuse thickening of the stratum corneum (the outer skin layer) from repeated friction or pressure — it forms as a protective response; estheticians may soften calluses with foot soaks and smooth them gently with a foot file or pumice stone, within the scope of esthetics practice", "A viral infection causing wart-like growths on pressure points of the foot", "A bone spur that protrudes through the skin on the heel or ball of the foot", "A fungal infection of the foot that forms as a hard plaque on the sole"], options_es: ["Un engrosamiento difuso del estrato córneo (la capa exterior de la piel) por fricción o presión repetida — se forma como respuesta protectora; los esteticistas pueden suavizar los callos con baños de pies y alisarlos suavemente con una lima para pies o piedra pómez, dentro del alcance de la práctica de estética", "Una infección viral que causa crecimientos similares a verrugas en los puntos de presión del pie", "Un espolón óseo que sobresale a través de la piel en el talón o el antepié del pie", "Una infección fúngica del pie que se forma como una placa dura en la planta del pie"], correct: 0, explanation: "Calluses (tylomas) are areas of hyperkeratosis — thickened, hardened stratum corneum — that develop in response to repetitive mechanical stress (friction from footwear, weight-bearing). They are protective responses. Estheticians may perform callus softening (enzymatic treatments, foot soaks) and reduction (foot file, pumice, safety blade) within their scope. Corns (nucleated calluses) with a central core are similar but more focused." },
  { id: 260, question: "A corn (heloma) on the foot differs from a callus in that:", question_es: "Un callo (heloma) en el pie se diferencia de un callo difuso en que:", options: ["A corn has a central hard core (nucleus) and is more sharply circumscribed — it develops from concentrated localized pressure (often from tight footwear) and can be painful; corns over bony prominences (hard corns) and between toes (soft corns) require gentle care within esthetics scope", "Corns are caused by viral infection (HPV) while calluses form from pressure", "Corns are raised above the skin surface while calluses are depressed into the skin", "There is no meaningful clinical difference between a corn and a callus — they are the same condition"], options_es: ["Un callo duro tiene un núcleo central duro (núcleo) y está más claramente circunscrito — se desarrolla a partir de una presión localizada concentrada (a menudo de calzado apretado) y puede ser doloroso; los callos duros sobre prominencias óseas (callos duros) y entre los dedos (callos blandos) requieren un cuidado suave dentro del alcance de estética", "Los callos duros son causados por infección viral (VPH) mientras que los callos difusos se forman por presión", "Los callos duros están elevados sobre la superficie de la piel mientras que los callos difusos están hundidos en la piel", "No hay diferencia clínica significativa entre un callo duro y un callo difuso — son la misma condición"], correct: 0, explanation: "Corns are focused hyperkeratotic lesions with a central translucent hard nucleus that points inward into the dermis — the nucleus causes pain when pressed. Hard corns (heloma durum) appear over bony prominences (top/sides of toes). Soft corns (heloma molle) appear between toes and are kept moist by sweat. Gentle mechanical reduction of corns is within esthetics scope; very deep or infected corns require podiatric care." },
  { id: 261, question: "A pumice stone used during pedicure services for callus smoothing must be:", question_es: "Una piedra pómez usada durante los servicios de pedicura para alisar los callos debe ser:", options: ["Either single-use (disposable) or properly cleaned and disinfected between clients — pumice is porous and may harbor microorganisms if not properly sanitized; some establishments use disposable pumice pads for single-client use", "Shared between clients without disinfection — pumice stone surfaces are self-cleaning from abrasion", "Boiled in water for 30 minutes to sterilize before each client use", "Replaced only when visibly worn — no disinfection protocol is required for pumice stones"], options_es: ["De uso único (desechable) o correctamente limpiada y desinfectada entre clientes — la pómez es porosa y puede albergar microorganismos si no se sanea adecuadamente; algunos establecimientos usan almohadillas de pómez desechables para uso de un solo cliente", "Compartida entre clientes sin desinfección — las superficies de la piedra pómez son auto-limpiadoras por abrasión", "Hervida en agua durante 30 minutos para esterilizar antes del uso de cada cliente", "Reemplazada solo cuando está visiblemente desgastada — no se requiere ningún protocolo de desinfección para las piedras pómez"], correct: 0, explanation: "Pumice stones are porous volcanic rock — pores trap skin cells, bacteria, and moisture, making them difficult to disinfect reliably. Best practice: single-use disposable pumice pads per client. If reusable pumice is used: clean thoroughly with a brush under water, then soak in EPA-registered disinfectant for full contact time, rinse, dry completely. Some state regulations prohibit reuse of porous implements." },
  { id: 262, question: "A foot file (also called a foot rasp or paddle) used in pedicure services:", question_es: "Una lima para pies (también llamada raspador o paleta para pies) usada en los servicios de pedicura:", options: ["Must be cleaned and disinfected between clients if it is a non-porous metal or sanitizable type — or used as a single-use disposable product; metal foot files can be properly disinfected; wooden or foam files are single-use only due to their porous nature", "Can be shared between clients without disinfection because foot skin is not sensitive to cross-contamination", "Requires autoclave sterilization before each client because it contacts the foot's skin directly", "Does not require any sanitation protocol — foot files are used below the infection control threshold"], options_es: ["Debe limpiarse y desinfectarse entre clientes si es un tipo de metal no poroso o saneables — o usarse como un producto desechable de uso único; las limas de pies de metal pueden desinfectarse adecuadamente; las limas de madera o espuma son de uso único solo debido a su naturaleza porosa", "Puede compartirse entre clientes sin desinfección porque la piel del pie no es sensible a la contaminación cruzada", "Requiere esterilización en autoclave antes de cada cliente porque contacta directamente la piel del pie", "No requiere ningún protocolo de saneamiento — las limas para pies están por debajo del umbral de control de infecciones"], correct: 0, explanation: "Foot files contact the client's skin (potentially compromised with calluses, cracked heels, or minor abrasions) and remove skin cells. Infection control classification: metal/stainless files are non-porous (can be disinfected); foam/wooden/emery-type files are porous (single-use). Metal files: clean with brush and soapy water, then disinfect per protocol. Porous files: discard after each client." },
  { id: 263, question: "Tinea pedis (athlete's foot) is relevant to pedicure services because:", question_es: "La tiña del pie (pie de atleta) es relevante para los servicios de pedicura porque:", options: ["Tinea pedis is a contagious fungal infection of the foot skin — active infection is a contraindication for pedicure services as the fungus can be transmitted to the esthetician, spread to other foot areas during service, and potentially contaminate the pedicure basin", "Tinea pedis is a viral infection that does not pose any cross-contamination risk in a pedicure setting", "Tinea pedis is not contagious — it only affects immunocompromised clients and is safe to service normally", "Only if the client has open blisters from tinea pedis is it a contraindication — dry, scaling tinea pedis can be treated normally"], options_es: ["La tiña del pie es una infección fúngica contagiosa de la piel del pie — la infección activa es una contraindicación para los servicios de pedicura ya que el hongo puede transmitirse al esteticista, propagarse a otras áreas del pie durante el servicio y potencialmente contaminar la cubeta de pedicura", "La tiña del pie es una infección viral que no plantea ningún riesgo de contaminación cruzada en un entorno de pedicura", "La tiña del pie no es contagiosa — solo afecta a clientes con inmunocompromiso y es seguro atenderla normalmente", "Solo si el cliente tiene ampollas abiertas por tiña del pie es una contraindicación — la tiña del pie seca y descamativa puede tratarse normalmente"], correct: 0, explanation: "Tinea pedis (ringworm of the foot) is caused by dermatophyte fungi and is highly contagious by contact with infected skin scales. It spreads easily in warm, moist environments — precisely the conditions of pedicure service. Active tinea pedis is a contraindication for pedicure services. The client should be referred to a physician for antifungal treatment and may return when the infection has resolved." },
  { id: 264, question: "A paraffin pedicure treatment differs from a paraffin manicure in that:", question_es: "Un tratamiento de pedicura con parafina difiere de una manicura con parafina en que:", options: ["The treatment area is the feet rather than the hands — the benefits are identical (deep moisturization, thermotherapy for comfort), but contraindications are especially important for feet (poor circulation, varicose veins, open wounds, active infection, heat sensitivity)", "Paraffin is only safe for use on hands — pedicure paraffin services are never performed due to safety concerns", "Pedicure paraffin is applied at higher temperatures than hand paraffin to penetrate the thicker foot skin", "No difference — all paraffin treatments are performed identically regardless of body area"], options_es: ["El área de tratamiento es los pies en lugar de las manos — los beneficios son idénticos (hidratación profunda, termoterapia para la comodidad), pero las contraindicaciones son especialmente importantes para los pies (mala circulación, várices, heridas abiertas, infección activa, sensibilidad al calor)", "La parafina solo es segura para usar en las manos — los servicios de pedicura con parafina nunca se realizan debido a preocupaciones de seguridad", "La parafina de pedicura se aplica a temperaturas más altas que la parafina de manos para penetrar la piel más gruesa del pie", "Sin diferencia — todos los tratamientos de parafina se realizan de manera idéntica independientemente del área del cuerpo"], correct: 0, explanation: "Paraffin pedicure delivers the same thermotherapy and moisturization benefits as paraffin manicure. However, foot-specific contraindications are critical: peripheral vascular disease (poor circulation — heat can cause burns), varicose veins (heat worsens them), open wounds or active infections on the foot, heat-sensitive diabetic neuropathy (can't feel if too hot). Always check for foot-specific contraindications before pedicure paraffin." },
  { id: 265, question: "During a pedicure, the esthetician should perform which assessment before beginning the service?", question_es: "Durante una pedicura, el esteticista debe realizar cuál evaluación antes de comenzar el servicio?", options: ["Visual inspection of the feet and toenails for contraindications — including signs of fungal infection (thickened, discolored, crumbling nails), active skin infection, open wounds, varicose veins, ingrown toenails, warts, and any abnormal lesions requiring medical evaluation", "Only checking that the pedicure equipment is clean — no client foot assessment is required", "Only asking the client about their preferred polish color and nail shape before beginning", "Assessment is only required for clients over 65 years of age — younger clients do not require foot assessment before pedicure service"], options_es: ["Inspección visual de los pies y las uñas de los pies para detectar contraindicaciones — incluyendo signos de infección fúngica (uñas gruesas, decoloradas, desmoronadas), infección cutánea activa, heridas abiertas, várices, uñas encarnadas, verrugas y cualquier lesión anormal que requiera evaluación médica", "Solo verificar que el equipo de pedicura esté limpio — no se requiere evaluación del pie del cliente", "Solo preguntar al cliente sobre su color de esmalte preferido y la forma de la uña antes de comenzar", "La evaluación solo se requiere para clientes mayores de 65 años — los clientes más jóvenes no requieren evaluación del pie antes del servicio de pedicura"], correct: 0, explanation: "Pre-pedicure foot assessment is essential safety practice. The esthetician should visually inspect both feet (tops and soles) and all toenails before beginning. This identifies: contraindications (active infection, open wounds), conditions requiring service modification (diabetes, varicose veins), and conditions requiring medical referral (suspected fungal infection, undiagnosed lesions). Document findings in the client record." },
  { id: 266, question: "Which type of foot soak is most appropriate for softening dry, calloused feet before a pedicure?", question_es: "¿Qué tipo de baño de pies es más apropiado para suavizar los pies secos y con callos antes de una pedicura?", options: ["A warm water soak with softening/emollient additives (like glycerin, oils, or mild keratolytic agents) — warm water softens the stratum corneum and emollients help retain moisture, making mechanical callus reduction more effective and comfortable", "A hot water soak at the highest temperature the client can tolerate — heat alone is sufficient", "A cold water soak — cold temperatures harden callus tissue, making it easier to remove in larger pieces", "A bleach-diluted soak — sodium hypochlorite softens calluses while simultaneously disinfecting the feet"], options_es: ["Un baño de agua tibia con aditivos suavizantes/emolientes (como glicerina, aceites o agentes queratolíticos suaves) — el agua tibia suaviza el estrato córneo y los emolientes ayudan a retener la humedad, haciendo que la reducción mecánica del callo sea más efectiva y cómoda", "Un baño de agua caliente a la temperatura más alta que el cliente pueda tolerar — el calor solo es suficiente", "Un baño de agua fría — las bajas temperaturas endurecen el tejido del callo, facilitando su extracción en trozos más grandes", "Un baño diluido con lejía — el hipoclorito de sodio suaviza los callos mientras simultáneamente desinfecta los pies"], correct: 0, explanation: "Pedicure foot soaks work by hydrating and softening the stratum corneum. Warm water (not hot — burns risk, especially for diabetic clients) is the primary softening agent. Additives enhance the effect: emollients (oils, glycerin) hydrate and soften, keratolytics (salicylic acid, urea) chemically digest keratin bonds in calluses. Properly softened calluses are safer and more comfortable to reduce mechanically." },
  { id: 267, question: "Nail hardeners containing formaldehyde are:", question_es: "Los endurecedores de uñas que contienen formaldehído son:", options: ["Effective at hardening nails by cross-linking nail plate proteins, but formaldehyde can cause allergic contact dermatitis and nail fold irritation with repeated use — formaldehyde-free alternatives using proteins, calcium, or polyurethane have become popular for sensitive clients", "Banned in all nail products by the FDA and TDLR — formaldehyde in any concentration is never permitted", "Completely safe for all clients with no documented side effects at cosmetic concentrations", "Only available by prescription from a dermatologist — not available in professional esthetics supply channels"], options_es: ["Efectivos para endurecer las uñas al entrecruzar las proteínas de la placa ungueal, pero el formaldehído puede causar dermatitis de contacto alérgica e irritación del pliegue ungueal con uso repetido — las alternativas sin formaldehído que usan proteínas, calcio o poliuretano se han vuelto populares para clientes sensibles", "Prohibidos en todos los productos de uñas por la FDA y TDLR — el formaldehído en cualquier concentración nunca está permitido", "Completamente seguros para todos los clientes sin efectos secundarios documentados a concentraciones cosméticas", "Solo disponibles con receta de un dermatólogo — no disponibles en los canales de suministro profesional de estética"], correct: 0, explanation: "Formaldehyde-containing nail hardeners work by cross-linking (tanning) the keratin proteins in the nail plate, making it harder. However, with repeated use, formaldehyde causes: contact sensitization, allergic reactions (dermatitis at nail fold), and paradoxically can cause nail brittleness from over-cross-linking. Formaldehyde-free alternatives (protein, calcium, nylon fiber reinforcement) are gentler options." },
  { id: 268, question: "The primary difference between a spa manicure and a standard manicure is:", question_es: "La diferencia principal entre una manicura de spa y una manicura estándar es:", options: ["A spa manicure includes enhanced treatment steps beyond basic nail care — such as exfoliation (scrub or enzyme), mask application, extended massage, and additional moisturizing treatments — providing a more luxurious, therapeutic experience", "A spa manicure uses more expensive polish — the product brand determines whether a service is 'spa' or 'standard'", "A spa manicure omits the base and top coat — it is a polish-free service", "A spa manicure includes nail tip application and enhancement as standard components"], options_es: ["Una manicura de spa incluye pasos de tratamiento mejorados más allá del cuidado básico de las uñas — como exfoliación (exfoliante o enzima), aplicación de mascarilla, masaje extendido y tratamientos adicionales de hidratación — proporcionando una experiencia más lujosa y terapéutica", "Una manicura de spa usa esmalte más caro — la marca del producto determina si un servicio es 'spa' o 'estándar'", "Una manicura de spa omite la base y el top coat — es un servicio sin esmalte", "Una manicura de spa incluye la aplicación de puntas de uñas y mejoras como componentes estándar"], correct: 0, explanation: "A spa (deluxe) manicure expands the standard manicure menu to include: exfoliation (sugar scrub, enzyme peel, or AHA treatment), masque application (hydrating, detoxifying), hot towel wrap, extended massage, hot oil treatment, paraffin dip, or aromatherapy elements. It enhances the therapeutic and relaxation aspects of the service beyond nail aesthetics alone." },
  { id: 269, question: "When a client shows signs of a potential allergic reaction to a nail product (redness, swelling, itching at the nail fold) during a service:", question_es: "Cuando un cliente muestra signos de una posible reacción alérgica a un producto de uñas (enrojecimiento, hinchazón, picazón en el pliegue ungueal) durante un servicio:", options: ["Stop using the product immediately, remove any product that has been applied if possible (before polymerization), rinse the area thoroughly with soap and water, apply cool compress if needed, and document the reaction — if symptoms are severe, refer to medical care", "Apply more product to dilute the allergenic concentration causing the reaction", "Continue the service but apply product more slowly — the reaction will subside with time", "Apply hydrocortisone cream immediately and continue the service — this resolves most nail allergies during service"], options_es: ["Dejar de usar el producto de inmediato, eliminar cualquier producto que se haya aplicado si es posible (antes de la polimerización), enjuagar el área a fondo con jabón y agua, aplicar una compresa fría si es necesario y documentar la reacción — si los síntomas son graves, derivar a atención médica", "Aplicar más producto para diluir la concentración alergénica que causa la reacción", "Continuar el servicio pero aplicar el producto más lentamente — la reacción disminuirá con el tiempo", "Aplicar crema de hidrocortisona de inmediato y continuar el servicio — esto resuelve la mayoría de las alergias de uñas durante el servicio"], correct: 0, explanation: "Allergic reactions to nail products (especially acrylics — HEMA, EMA, MMA — and adhesives) can progress rapidly. Immediate action: discontinue product use, remove uncured product carefully, rinse thoroughly. Sensitized clients develop stronger reactions with each subsequent exposure — there is no 'push through.' Document the specific product, patch test in future, and select hypoallergenic alternatives. Anaphylaxis (rare) requires emergency care." },
  { id: 270, question: "The 3-free, 5-free, and 7-free designations on nail polish labels refer to:", question_es: "Las designaciones 3-free, 5-free y 7-free en las etiquetas de esmalte de uñas se refieren a:", options: ["The number of potentially harmful chemicals that have been omitted from the formula — 3-free excludes formaldehyde, toluene, and DBP; 5-free adds formaldehyde resin and camphor; 7-free further excludes ethyl tosylamide and xylene — these designations indicate cleaner formulations", "The number of coats of polish that the formula requires for full opacity", "Certifications indicating the product is free from the top 3, 5, or 7 most common allergens", "The minimum age restriction — 3-free is for ages 3 and up, 5-free for ages 5 and up, etc."], options_es: ["El número de químicos potencialmente dañinos que se han omitido de la fórmula — 3-free excluye formaldehído, tolueno y DBP; 5-free añade resina de formaldehído y alcanfor; 7-free excluye además tosilamida de etilo y xileno — estas designaciones indican formulaciones más limpias", "El número de capas de esmalte que la fórmula requiere para opacidad completa", "Certificaciones que indican que el producto está libre de los 3, 5 o 7 alérgenos más comunes", "La restricción de edad mínima — 3-free es para mayores de 3 años, 5-free para mayores de 5 años, etc."], correct: 0, explanation: "The 'X-free' marketing terms indicate omission of specific chemicals historically included in nail polish formulations: 3-free (no formaldehyde, toluene, dibutyl phthalate/DBP), 5-free (adds no formaldehyde resin, camphor), 7-free (adds no ethyl tosylamide, xylene), 10-free, etc. These designations are unregulated marketing terms — no government body verifies these claims independently." },
  { id: 271, question: "A nail wrap (silk, fiberglass, or linen wrap) applied to a natural nail:", question_es: "Una envoltura de uñas (envoltura de seda, fibra de vidrio o lino) aplicada a una uña natural:", options: ["Reinforces a weak, thin, or cracked natural nail by bonding a mesh fabric to the nail plate with adhesive — providing structural support without the bulk of acrylic; wrap fabrics are cut to size, applied with resin (cyanoacrylate), and finished with resin activator and a top sealer", "Replaces the natural nail entirely with an artificial structure", "Is applied only for decorative nail art purposes — wraps have no structural reinforcing function", "Contains formaldehyde that cross-links the nail plate to create hardening"], options_es: ["Refuerza una uña natural débil, delgada o agrietada al unir un tejido de malla a la placa ungueal con adhesivo — proporcionando soporte estructural sin el grosor del acrílico; los tejidos de envoltura se cortan a medida, se aplican con resina (cianoacrilato) y se terminan con activador de resina y un sellador superior", "Reemplaza la uña natural por completo con una estructura artificial", "Se aplica solo con fines de arte de uñas decorativo — las envolturas no tienen ninguna función de refuerzo estructural", "Contiene formaldehído que entrelazan la placa ungueal para crear endurecimiento"], correct: 0, explanation: "Nail wraps (silk, fiberglass, or linen) are a nail overlay system that uses fabric mesh + adhesive resin to reinforce the natural nail plate. The mesh provides tensile strength that prevents further cracking or breakage. Silk wraps are popular for their thin, flexible finish. They are a less-heavy alternative to acrylic but require careful application to avoid product lifting." },
  { id: 272, question: "Nail thinner (used to thin nail polish that has become thick) is:", question_es: "El adelgazador de esmalte de uñas (usado para adelgazar el esmalte de uñas que se ha espesado) es:", options: ["A solvent product formulated to restore the original consistency of thickened nail polish — it contains the same solvents as the original polish (typically ethyl acetate, butyl acetate) and should be added one drop at a time; it is not the same as nail polish remover", "Nail polish remover used in small amounts — remover and thinner are functionally identical", "Water — adding a few drops of water restores polish consistency effectively", "Acetone — the same chemical as in regular nail polish remover, just in smaller quantity"], options_es: ["Un producto solvente formulado para restaurar la consistencia original del esmalte de uñas espesado — contiene los mismos solventes que el esmalte original (típicamente acetato de etilo, acetato de butilo) y debe añadirse una gota a la vez; no es lo mismo que el removedor de esmalte de uñas", "Removedor de esmalte de uñas usado en pequeñas cantidades — el removedor y el adelgazador son funcionalmente idénticos", "Agua — añadir unas pocas gotas de agua restaura la consistencia del esmalte de forma efectiva", "Acetona — el mismo químico que en el removedor de esmalte de uñas regular, solo en menor cantidad"], correct: 0, explanation: "Nail thinner and nail polish remover are NOT interchangeable. Nail thinner = solvent blend (ethyl or butyl acetate-based) formulated specifically to thin polish without disrupting the polymer matrix — it restores viscosity without breaking down the film-forming resins. Nail polish remover (acetone or non-acetone) breaks down polish completely — adding it to a bottle destroys the polish by dissolving its polymer components." },
  { id: 273, question: "When performing a nail service, the ventilation of the nail area is important because:", question_es: "Al realizar un servicio de uñas, la ventilación del área de uñas es importante porque:", options: ["Nail products (especially acrylics, gel removers, and nail polish removers) emit volatile organic compounds (VOCs) and monomers that can irritate the esthetician's respiratory tract, eyes, and skin with repeated daily exposure — adequate ventilation protects occupational health", "Ventilation only affects the drying speed of nail polish — no health concerns exist for nail vapors", "Ventilation is only required when using high-temperature nail lamps", "Only clients need protection from nail fumes — the esthetician's occupational exposure is regulated only by personal choice"], options_es: ["Los productos de uñas (especialmente los acrílicos, los removedores de gel y los removedores de esmalte de uñas) emiten compuestos orgánicos volátiles (COV) y monómeros que pueden irritar el tracto respiratorio, los ojos y la piel del esteticista con exposición diaria repetida — la ventilación adecuada protege la salud ocupacional", "La ventilación solo afecta la velocidad de secado del esmalte de uñas — no existen preocupaciones de salud para los vapores de uñas", "La ventilación solo se requiere cuando se usan lámparas de uñas de alta temperatura", "Solo los clientes necesitan protección de los humos de uñas — la exposición ocupacional del esteticista está regulada solo por elección personal"], correct: 0, explanation: "Nail service areas produce significant chemical vapors — acrylic monomer (EMA), acetone (polish remover and gel remover), ethyl acetate, cyanoacrylate adhesive fumes, and others. Repeated daily exposure (occupational) creates health risks for estheticians: respiratory sensitization, eye/mucous membrane irritation, and potential systemic effects. Proper ventilation (local exhaust at the nail table or general room ventilation) is an OSHA requirement." },
  { id: 274, question: "An esthetician should recommend a physician consultation before providing nail services when a client presents with:", question_es: "Un esteticista debe recomendar una consulta médica antes de proporcionar servicios de uñas cuando un cliente presenta:", options: ["Undiagnosed unusual nail changes (unusual pigmentation, rapid texture change, lesions around the nail), signs of systemic disease reflected in the nails, active infection, severe vascular compromise, or any condition where service could pose a health risk", "A simple nail breakage — nail breaks always warrant physician clearance before any manicure", "Any nail with natural ridging — longitudinal ridges require medical diagnosis before nail services", "A request for gel nails — gel products require physician approval before professional application"], options_es: ["Cambios inusuales en las uñas no diagnosticados (pigmentación inusual, cambio rápido de textura, lesiones alrededor de la uña), signos de enfermedad sistémica reflejados en las uñas, infección activa, compromiso vascular grave o cualquier condición donde el servicio podría representar un riesgo para la salud", "Una simple rotura de uña — las roturas de uñas siempre requieren autorización médica antes de cualquier manicura", "Cualquier uña con estrías naturales — las estrías longitudinales requieren diagnóstico médico antes de los servicios de uñas", "Una solicitud de uñas de gel — los productos de gel requieren aprobación médica antes de la aplicación profesional"], correct: 0, explanation: "Medical referral for nail concerns: any undiagnosed new nail change (especially dark longitudinal bands, rapidly progressing discoloration, nodules near the nail), active infection, onychomycosis (requires prescription treatment), suspected systemic disease markers (clubbing, Terry's nails), severe circulation compromise, or when service could harm the client. Referral protects both the client and the esthetician from practicing beyond scope." },
  { id: 275, question: "The correct way to store nail polish in an esthetics establishment to maintain product quality is:", question_es: "La forma correcta de almacenar el esmalte de uñas en un establecimiento de estética para mantener la calidad del producto es:", options: ["Store upright in a cool, dry location away from direct sunlight and extreme temperatures — UV light and heat cause polish solvents to evaporate and components to degrade; keep caps tightly closed and wipe bottle necks clean to prevent polish from sealing the cap shut", "Store upside-down — inverted storage prevents solvent separation and air exposure", "Store in the refrigerator — cold temperatures preserve nail polish formulations indefinitely", "Store with caps loosely in place — tightly closed caps create pressure that degrades the polish"], options_es: ["Almacenar verticalmente en un lugar fresco y seco alejado de la luz solar directa y las temperaturas extremas — la luz UV y el calor hacen que los solventes del esmalte se evaporen y los componentes se degraden; mantener los tapones bien cerrados y limpiar los cuellos de las botellas para evitar que el esmalte selle el tapón", "Almacenar boca abajo — el almacenamiento invertido previene la separación de solventes y la exposición al aire", "Almacenar en el refrigerador — las bajas temperaturas preservan las formulaciones de esmalte de uñas indefinidamente", "Almacenar con los tapones colocados sin apretar — los tapones bien cerrados crean presión que degrada el esmalte"], correct: 0, explanation: "Nail polish should be stored: (1) upright (prevents solvent separation at cap), (2) tightly closed (prevents evaporation of volatile solvents — the primary cause of thickening), (3) away from heat and light (UV breaks down pigments and film formers), (4) moderate temperature (refrigeration can temporarily improve some polishes but isn't standard practice and can cause condensation issues). Wipe bottle necks to prevent cap sealing." },
  { id: 276, question: "Plantar warts (verruca plantaris) encountered on a client's foot during a pedicure assessment:", question_es: "Las verrugas plantares (verruca plantaris) encontradas en el pie de un cliente durante una evaluación de pedicura:", options: ["Are a contraindication for pedicure service in the affected area — they are caused by HPV and are contagious; mechanical trauma (foot file, pumice) over warts can spread the virus and the implements become contaminated; the client should be referred to a physician for treatment", "Are benign calluses that should be aggressively reduced with a foot file during the pedicure to improve appearance", "Do not pose a cross-contamination risk because HPV cannot survive on implements and surfaces", "Can be treated during the pedicure service with over-the-counter salicylic acid products applied by the esthetician"], options_es: ["Son una contraindicación para el servicio de pedicura en el área afectada — son causadas por el VPH y son contagiosas; el trauma mecánico (lima para pies, pómez) sobre las verrugas puede diseminar el virus y los implementos quedan contaminados; el cliente debe ser derivado a un médico para tratamiento", "Son callos benignos que deben reducirse agresivamente con una lima para pies durante la pedicura para mejorar la apariencia", "No representan un riesgo de contaminación cruzada porque el VPH no puede sobrevivir en implementos y superficies", "Pueden tratarse durante el servicio de pedicura con productos de ácido salicílico de venta libre aplicados por el esteticista"], correct: 0, explanation: "Plantar warts are HPV infections of the plantar foot surface. Mechanical trauma (filing, pumice) over warts: (1) spreads the virus to adjacent areas, (2) contaminates implements and the pedicure basin. HPV can survive on surfaces. Service in the affected area is contraindicated — service on unaffected areas may proceed with careful isolation. Client needs medical or dermatological treatment for wart resolution." },
  { id: 277, question: "A nail client who is pregnant should be advised regarding nail services that:", question_es: "Una cliente de uñas que está embarazada debe ser asesorada con respecto a los servicios de uñas que:", options: ["Standard nail polish services are generally considered low-risk; however, gel and acrylic nail services involve chemical vapors and UV exposure that should be minimized — ensuring excellent ventilation, shorter exposure times, and UV lamp shielding are reasonable precautions during pregnancy", "All nail services are prohibited during pregnancy without physician written approval", "Pregnancy has no bearing on nail service decisions — all products and services are identical for pregnant clients", "Only base coat must be avoided during pregnancy — color and top coat products are safe with no restrictions"], options_es: ["Los servicios de esmalte de uñas estándar generalmente se consideran de bajo riesgo; sin embargo, los servicios de gel y uñas acrílicas involucran vapores químicos y exposición UV que deben minimizarse — garantizar una excelente ventilación, tiempos de exposición más cortos y protección de la lámpara UV son precauciones razonables durante el embarazo", "Todos los servicios de uñas están prohibidos durante el embarazo sin aprobación escrita del médico", "El embarazo no tiene ningún efecto en las decisiones de servicio de uñas — todos los productos y servicios son idénticos para las clientas embarazadas", "Solo el base coat debe evitarse durante el embarazo — los productos de color y top coat son seguros sin restricciones"], correct: 0, explanation: "Pregnancy nail service considerations: (1) regular nail polish — generally low-risk, especially 5-free/7-free formulations; (2) acrylics — chemical monomer vapors; (3) gel UV curing — UV exposure; (4) gel removal (acetone) — solvent exposure. While definitive evidence of harm is limited, minimizing chemical and UV exposure during pregnancy is a reasonable precaution. Ensure excellent ventilation for any nail service." },
  { id: 278, question: "After removal of a full set of acrylic nail enhancements, a client's natural nails may appear thin and fragile because:", question_es: "Después de la extracción de un juego completo de mejoras de uñas acrílicas, las uñas naturales de un cliente pueden parecer delgadas y frágiles porque:", options: ["The nail plate was buffed/filed during enhancement application and removal, removing surface layers of the nail's keratin; the nail was also protected from environmental hardening during the enhancement period — nail plate recovery takes several weeks with proper nail care", "Acrylic chemicals permanently dissolve nail plate keratin — damage from acrylics is irreversible", "The nails absorbed the acrylic monomer which weakened the keratin structure permanently", "Natural nail thinning after enhancements is a sign of nail fungal infection that always develops under enhancements"], options_es: ["La placa ungueal fue limada/pulida durante la aplicación y remoción de mejoras, eliminando las capas superficiales de la queratina de la uña; la uña también fue protegida del endurecimiento ambiental durante el período de mejora — la recuperación de la placa ungueal toma varias semanas con el cuidado adecuado de las uñas", "Los químicos acrílicos disuelven permanentemente la queratina de la placa ungueal — el daño de los acrílicos es irreversible", "Las uñas absorbieron el monómero acrílico que debilitó la estructura de queratina permanentemente", "El adelgazamiento de la uña natural después de las mejoras es un signo de infección fúngica de las uñas que siempre se desarrolla bajo las mejoras"], correct: 0, explanation: "Post-enhancement nail thinning results from: (1) mechanical filing during application (preparation of the nail surface) and removal, (2) the nail plate not experiencing normal hardening from environmental exposure (UV, air), and (3) acetone exposure during soak-off (temporarily dehydrates nails). Recovery: weeks to months of proper nail care (cuticle oils, nail hardener, gentle handling), as new nail plate grows out from the matrix." },
  { id: 279, question: "A client with nail enhancements (acrylics or gels) notices a green discoloration appearing between the enhancement and the natural nail. This indicates:", question_es: "Un cliente con mejoras de uñas (acrílicos o geles) nota una decoloración verde que aparece entre la mejora y la uña natural. Esto indica:", options: ["A bacterial infection (usually Pseudomonas aeruginosa) that has colonized the space created by a lifted enhancement — the green pigment (pyocyanin) is produced by the bacteria; the enhancement must be removed, the natural nail treated, and the area must heal before reapplication", "Normal oxidation of the acrylic or gel product from UV exposure — not an infection", "A fungal nail infection — green color always indicates onychomycosis", "Vitamin E product applied beneath the enhancement for nail health is pigmenting the nail green"], options_es: ["Una infección bacteriana (generalmente Pseudomonas aeruginosa) que ha colonizado el espacio creado por una mejora levantada — el pigmento verde (piocianina) es producido por las bacterias; la mejora debe eliminarse, la uña natural tratarse y el área debe sanar antes de la reaplicación", "Oxidación normal del producto acrílico o de gel por exposición UV — no es una infección", "Una infección fúngica de las uñas — el color verde siempre indica onicomicosis", "El producto de vitamina E aplicado debajo de la mejora para la salud de la uña está pigmentando la uña de verde"], correct: 0, explanation: "Green nail syndrome (chloronychia) in the context of nail enhancements is a Pseudomonas aeruginosa bacterial infection. Pseudomonas thrives in the moist, protected space created when an enhancement lifts — it produces green-blue pyocyanin pigment. Treatment: remove the enhancement, dry the natural nail, and allow healing. Reapplication before complete healing risks recurrence." },
  { id: 280, question: "To safely remove an acrylic enhancement that has become damaged or needs replacement:", question_es: "Para eliminar de forma segura una mejora acrílica que se ha dañado o necesita reemplazarse:", options: ["Soak a cotton pad in 100% acetone, place over the nail, wrap with foil, wait 15–20 minutes, and gently scrape softened acrylic with an orangewood stick — never forcefully peel, as peeling removes natural nail plate layers with the acrylic", "Use a metal implement to lever and peel the acrylic from the nail plate — this is the fastest method", "Soak the hand in water for 30 minutes — water dissolves acrylic enhancements effectively", "File the acrylic down to the natural nail with an electric file as quickly as possible"], options_es: ["Remojar una almohadilla de algodón en acetona al 100%, colocarla sobre la uña, envolver con papel de aluminio, esperar 15–20 minutos y raspar suavemente el acrílico suavizado con un palito de naranja — nunca pelar con fuerza, ya que pelar elimina las capas de la placa ungueal natural junto con el acrílico", "Usar un implemento de metal para hacer palanca y pelar el acrílico de la placa ungueal — este es el método más rápido", "Remojar la mano en agua durante 30 minutos — el agua disuelve las mejoras acrílicas de forma efectiva", "Limar el acrílico hasta la uña natural con una lima eléctrica lo más rápido posible"], correct: 0, explanation: "Acrylic soak-off technique: (1) file surface to break the seal coat, (2) soak acetone-saturated cotton directly on enhancement, (3) wrap tightly with foil, (4) wait full time (15–20+ minutes for acrylics — they are more resistant than gel polish), (5) check softening, (6) gently slide/scrape softened acrylic, repeat if needed. Peeling pulls off natural nail plate layers — this is a common cause of nail plate damage." },
  { id: 281, question: "What is the purpose of wrapping the free edge when applying nail polish?", question_es: "¿Cuál es el propósito de envolver el borde libre al aplicar esmalte de uñas?", options: ["Wrapping (running the brush tip under and around the free edge to seal it with polish) prevents tip chipping — the free edge is the most vulnerable area where chipping begins; sealing it with base coat, color, and top coat creates a complete 'envelope' of protection", "Wrapping the free edge applies polish to the underside of the nail — this is purely cosmetic", "Wrapping is done to apply cuticle oil to the nail tip at the end of the service", "Wrapping the free edge is an outdated technique with no proven benefit to polish longevity"], options_es: ["Envolver (pasar la punta del pincel por debajo y alrededor del borde libre para sellarlo con esmalte) previene el astillamiento de la punta — el borde libre es el área más vulnerable donde comienza el astillamiento; sellarlo con base coat, color y top coat crea un 'sobre' completo de protección", "Envolver el borde libre aplica esmalte en la parte inferior de la uña — esto es puramente cosmético", "El envolver se hace para aplicar aceite de cutícula en la punta de la uña al final del servicio", "Envolver el borde libre es una técnica obsoleta sin ningún beneficio comprobado para la longevidad del esmalte"], correct: 0, explanation: "The free edge tip is the first point of contact with external surfaces and the most common starting point for polish chipping. Wrapping seals all three polish layers (base, color, top coat) around and under the free edge, creating a complete seal. This is one of the most effective techniques for extending manicure longevity. Most chip failures start at the unsealed free edge." },
  { id: 282, question: "Proper nail plate preparation before any polish or enhancement application includes:", question_es: "La preparación adecuada de la placa ungueal antes de cualquier aplicación de esmalte o mejoras incluye:", options: ["Removing all old product, shaping the nail, gently pushing back cuticle, cleansing the nail plate surface to remove oils and residue (with nail cleanser or isopropyl alcohol), allowing to dry completely — oil and moisture on the nail surface prevent adhesion of all nail products", "Only buffing the nail surface with a 100-grit buffer until shiny — no cleansing is needed", "Soaking in water for 20 minutes to ensure the nail plate is fully hydrated before product application", "Applying cuticle oil first to condition the nail before polish — oil improves polish adherence"], options_es: ["Eliminar todo el producto antiguo, dar forma a la uña, empujar suavemente la cutícula hacia atrás, limpiar la superficie de la placa ungueal para eliminar los aceites y residuos (con limpiador de uñas o alcohol isopropílico), dejar secar completamente — el aceite y la humedad en la superficie de la uña impiden la adherencia de todos los productos de uñas", "Solo pulir la superficie de la uña con un buffer de 100 granos hasta que brille — no se necesita limpieza", "Remojar en agua durante 20 minutos para asegurarse de que la placa ungueal esté completamente hidratada antes de la aplicación del producto", "Aplicar aceite de cutícula primero para acondicionar la uña antes del esmalte — el aceite mejora la adherencia del esmalte"], correct: 0, explanation: "Nail preparation sequence: remove old product → shape → cuticle care → cleanse (IPA/nail cleanser wipe to degrease) → dry → apply product. The critical step is degreasing — natural nail oils, skin oils from handling, and moisturizing products create a barrier that prevents nail product adhesion. Products applied to oily, moist nails lift prematurely regardless of quality." },
  { id: 283, question: "When a client wants to grow out their natural nails after years of wearing enhancements, an esthetician can recommend:", question_es: "Cuando una cliente quiere dejar crecer sus uñas naturales después de años de usar mejoras, un esteticista puede recomendar:", options: ["Nail hardeners or strengtheners to support fragile post-enhancement nails, regular applications of cuticle oil for daily moisture, keeping nails trimmed to a manageable length while growing, and a healthy diet (adequate protein and biotin) to support nail growth", "Immediately applying a new set of enhancements — this is the only way to protect growing natural nails", "Soaking nails in water twice daily to rehydrate them after acetone exposure", "Filing nails completely flat and avoiding all polish until they grow to full length"], options_es: ["Endurecedores o fortalecedores de uñas para apoyar las uñas frágiles post-mejoras, aplicaciones regulares de aceite de cutícula para humedad diaria, mantener las uñas recortadas a una longitud manejable mientras crecen y una dieta saludable (proteína adecuada y biotina) para apoyar el crecimiento de las uñas", "Aplicar inmediatamente un nuevo juego de mejoras — esta es la única forma de proteger las uñas naturales que crecen", "Remojar las uñas en agua dos veces al día para rehidratarlas después de la exposición a la acetona", "Limar las uñas completamente planas y evitar todo esmalte hasta que crezcan a su longitud completa"], correct: 0, explanation: "Natural nail recovery after enhancements: (1) nail strengthener/hardener to reinforce the thinned plate while new growth emerges, (2) daily cuticle oil (keeps cuticle and nail plate supple — reduces breakage), (3) gentle filing to maintain manageable length as nails grow, (4) protective base coat with polish to reduce environmental damage, (5) nutrition — protein (keratin precursor) and biotin support nail plate formation." },
  { id: 284, question: "A nail primer that is 'acid-free' is different from a traditional methacrylic acid primer because:", question_es: "Un imprimante de uñas que es 'sin ácido' es diferente de un imprimante tradicional de ácido metacrílico porque:", options: ["Acid-free primers use hydrogen bonding to bond to the nail plate — they are gentler on the surrounding skin and nail fold (no caustic burn risk), but generally require more precise nail preparation for equivalent adhesion results compared to acid primers", "Acid-free primers contain a higher concentration of methacrylic acid — 'acid-free' refers to free acid radicals, not absence of acid", "Acid primers are safer than acid-free primers — 'acid-free' is a marketing term with no real formulation difference", "Acid-free primers only work with gel systems — they cannot be used with acrylic nail products"], options_es: ["Los imprimantes sin ácido usan la unión de hidrógeno para unirse a la placa ungueal — son más suaves en la piel circundante y el pliegue ungueal (sin riesgo de quemadura cáustica), pero generalmente requieren una preparación de uñas más precisa para resultados de adherencia equivalentes en comparación con los imprimantes de ácido", "Los imprimantes sin ácido contienen una mayor concentración de ácido metacrílico — 'sin ácido' se refiere a radicales de ácido libre, no a la ausencia de ácido", "Los imprimantes de ácido son más seguros que los imprimantes sin ácido — 'sin ácido' es un término de marketing sin diferencia real de formulación", "Los imprimantes sin ácido solo funcionan con sistemas de gel — no pueden usarse con productos de uñas acrílicas"], correct: 0, explanation: "Traditional acid nail primers (methacrylic acid) are caustic — they etch the nail surface and can cause severe chemical burns to skin/soft tissue if they contact them. Acid-free primers (usually methacrylate-based, forming hydrogen bonds and van der Waals forces) are much safer for surrounding tissue. Trade-off: acid-free requires more thorough degreasing for equivalent adhesion. Both improve enhancement retention." },
  { id: 285, question: "The purpose of a 'nail dehydrator' as a step separate from 'nail primer' in enhancement preparation is:", question_es: "El propósito de un 'deshidratador de uñas' como paso separado del 'imprimante de uñas' en la preparación de mejoras es:", options: ["Dehydrators remove surface moisture and oils (primarily with alcohol or acetone) as the first preparation step — then primer creates the actual chemical bond; doing both steps provides optimal adhesion conditions for enhancements", "Nail dehydrators and nail primers are the same product used under different brand names", "Dehydrators are applied after primer — they seal the primer to the nail plate", "Only one of the two products is needed — using both together can cause product incompatibility"], options_es: ["Los deshidratadores eliminan la humedad superficial y los aceites (principalmente con alcohol o acetona) como el primer paso de preparación — luego el imprimante crea el enlace químico real; hacer ambos pasos proporciona condiciones óptimas de adherencia para las mejoras", "Los deshidratadores de uñas y los imprimantes de uñas son el mismo producto usado con diferentes nombres de marca", "Los deshidratadores se aplican después del imprimante — sellan el imprimante en la placa ungueal", "Solo uno de los dos productos es necesario — usarlos juntos puede causar incompatibilidad de productos"], correct: 0, explanation: "Dehydrator and primer serve different sequential functions: (1) Dehydrator (IPA/acetone base) — removes surface oils and moisture first; (2) Primer — then creates a chemical bond (acid primer) or hydrogen bond (acid-free) to the dehydrated nail plate. Both steps together maximize adhesion. Using primer without dehydrating first means the primer bonds to oil/moisture residue rather than directly to nail keratin." },
  { id: 286, question: "Nail clients with a history of HEMA (2-hydroxyethyl methacrylate) allergy should be advised that:", question_es: "Los clientes de uñas con historial de alergia al HEMA (metacrilato de 2-hidroxietilo) deben ser informados de que:", options: ["HEMA is a common allergen found in many gel nail polish and hard gel products — clients with HEMA sensitivity may react to gel products containing it; HEMA-free gel formulations are available, and the esthetician should verify ingredient compatibility before service", "HEMA allergy prevents any nail service whatsoever — clients with HEMA allergy cannot receive manicure or pedicure services of any kind", "HEMA is found only in regular nail polish, not in gel products — clients with HEMA allergy can safely receive all gel nail services", "HEMA allergy is always outgrown within two years — clients with previous allergy can typically receive gel services after waiting two years"], options_es: ["El HEMA es un alérgeno común que se encuentra en muchos esmaltes de gel y productos de gel duro — los clientes con sensibilidad al HEMA pueden reaccionar a los productos de gel que lo contienen; las formulaciones de gel sin HEMA están disponibles y el esteticista debe verificar la compatibilidad de los ingredientes antes del servicio", "La alergia al HEMA previene cualquier servicio de uñas en absoluto — los clientes con alergia al HEMA no pueden recibir ningún tipo de servicio de manicura o pedicura", "El HEMA se encuentra solo en el esmalte de uñas regular, no en los productos de gel — los clientes con alergia al HEMA pueden recibir de forma segura todos los servicios de uñas de gel", "La alergia al HEMA siempre desaparece dentro de dos años — los clientes con alergia previa típicamente pueden recibir servicios de gel después de esperar dos años"], correct: 0, explanation: "HEMA (2-hydroxyethyl methacrylate) is a reactive monomer in many gel nail products that commonly causes allergic contact sensitization. Once sensitized, the client reacts to all products containing HEMA. HEMA-free gel formulations (using alternative monomers) are available for sensitized clients. Sensitization is lifelong — there is no 'growing out' of it, and reactions typically worsen with each subsequent exposure." },
  { id: 287, question: "The foot care service known as a 'callus peel' or enzymatic callus treatment uses:", question_es: "El servicio de cuidado de pies conocido como 'peel de callos' o tratamiento enzimático de callos utiliza:", options: ["Keratolytic enzymes (typically papain from papaya, bromelain from pineapple, or similar proteolytic enzymes) to chemically soften and dissolve the bonds between dead skin cells in the thickened stratum corneum — allowing gentle removal without aggressive mechanical abrasion", "Concentrated hydrochloric acid to chemically dissolve the callus tissue in a single application", "A combination of urea and salicylic acid at concentrations that require a physician's prescription", "Only physical abrasion — enzymatic products have no documented effect on callus tissue"], options_es: ["Enzimas queratolíticas (típicamente papaina de la papaya, bromelina de la piña o enzimas proteolíticas similares) para suavizar y disolver químicamente los enlaces entre las células muertas de la piel en el estrato córneo engrosado — permitiendo una extracción suave sin abrasión mecánica agresiva", "Ácido clorhídrico concentrado para disolver químicamente el tejido del callo en una sola aplicación", "Una combinación de urea y ácido salicílico a concentraciones que requieren la prescripción de un médico", "Solo abrasión física — los productos enzimáticos no tienen ningún efecto documentado en el tejido de callos"], correct: 0, explanation: "Enzymatic callus treatments use proteolytic enzymes (plant-derived: papain, bromelain, or others) that break down the peptide bonds in keratin proteins — selectively softening the dead, hyperkeratotic tissue while sparing living skin. They are gentler than mechanical abrasion and more targeted than chemical keratolytics. After application and dwell time, softened callus tissue wipes or files away easily." },
  { id: 288, question: "During a pedicure, the proper technique for treating dry, cracked heels includes:", question_es: "Durante una pedicura, la técnica adecuada para tratar talones secos y agrietados incluye:", options: ["Soaking to soften the heel skin, gently reducing the thickened skin with a foot file or callus tool within the depth appropriate for esthetics scope, applying a urea-based or emollient-rich foot cream, and recommending daily home care moisturization to maintain results", "Cutting the cracks open with a blade to remove all hardened tissue in one session regardless of depth", "Applying super glue to seal heel cracks — medical grade cyanoacrylate is the standard treatment", "Only applying polish — cracked heels cannot be treated during a pedicure service and always require medical referral"], options_es: ["Remojar para suavizar la piel del talón, reducir suavemente la piel engrosada con una lima para pies o herramienta de callos dentro de la profundidad apropiada para el alcance de estética, aplicar una crema de pies rica en urea o emolientes y recomendar el cuidado casero diario de hidratación para mantener los resultados", "Cortar las grietas con una hoja para eliminar todo el tejido endurecido en una sesión independientemente de la profundidad", "Aplicar superpegamento para sellar las grietas del talón — el cianoacrilato grado médico es el tratamiento estándar", "Solo aplicar esmalte — los talones agrietados no pueden tratarse durante un servicio de pedicura y siempre requieren derivación médica"], correct: 0, explanation: "Dry, fissured heels (cracked heels) result from lack of moisture, prolonged standing, improper footwear. Esthetics approach: (1) soak and soften, (2) gently reduce thickened callus with appropriate tools (foot file, safety blade — within scope), (3) apply urea cream (20–40% urea creams are effective keratolytics for heels), (4) home care instruction. Deeply fissured, bleeding heels may require podiatric or medical care." },
  { id: 289, question: "Foot massage performed during a pedicure service should be avoided or modified for clients with:", question_es: "El masaje de pies realizado durante un servicio de pedicura debe evitarse o modificarse para clientes con:", options: ["Peripheral vascular disease, phlebitis (inflamed veins), deep vein thrombosis (DVT) or history of DVT, severe edema, open wounds or active infection on the foot, or acute gout — massage can worsen these conditions or dislodge blood clots", "Bunions (hallux valgus) — bunions are an absolute contraindication for any foot massage", "Flat feet — foot massage is always contraindicated for clients with fallen arches", "Any foot condition at all — foot massage should only be performed on completely healthy feet without exception"], options_es: ["Enfermedad vascular periférica, flebitis (venas inflamadas), trombosis venosa profunda (TVP) o historial de TVP, edema grave, heridas abiertas o infección activa en el pie, o gota aguda — el masaje puede empeorar estas condiciones o desprender coágulos de sangre", "Juanetes (hallux valgus) — los juanetes son una contraindicación absoluta para cualquier masaje de pies", "Pies planos — el masaje de pies siempre está contraindicado para clientes con arcos caídos", "Cualquier condición del pie en absoluto — el masaje de pies solo debe realizarse en pies completamente sanos sin excepción"], correct: 0, explanation: "Foot massage contraindications: DVT (massage could dislodge thrombus, causing pulmonary embolism — serious!), phlebitis/inflamed veins, severe peripheral vascular disease, acute gout (extremely painful joints), edema from unknown cause, open wounds or active infection, and recent foot surgery. Modify massage (lighter pressure) for clients with varicose veins, diabetic neuropathy, or compromised sensation." },
  { id: 290, question: "An acrylic bead applied to a nail form or tip for a nail extension should be structured with:", question_es: "Una bola de acrílico aplicada a una forma de uña o punta para una extensión de uña debe estructurarse con:", options: ["Thinner product at the stress point (middle of the free edge extension), slightly thicker over the apex (the highest point of the nail — where maximum structural strength is needed), and thinning again toward the free edge tip — this convex shape provides the most durable structure", "An absolutely flat, uniform thickness from cuticle to tip — variations in thickness weaken the enhancement", "Maximum thickness at the free edge tip for durability and minimum at the apex", "As thick as possible throughout — more product always equals a stronger, more durable enhancement"], options_es: ["Producto más delgado en el punto de estrés (mitad de la extensión del borde libre), ligeramente más grueso sobre el ápice (el punto más alto de la uña — donde se necesita la máxima resistencia estructural) y adelgazándose nuevamente hacia la punta del borde libre — esta forma convexa proporciona la estructura más duradera", "Un grosor completamente plano y uniforme de la cutícula a la punta — las variaciones en el grosor debilitan la mejora", "Máximo grosor en la punta del borde libre para durabilidad y mínimo en el ápice", "Lo más grueso posible en toda la extensión — más producto siempre equivale a una mejora más fuerte y duradera"], correct: 0, explanation: "Nail enhancement structure follows the 'arch theory' — the natural nail's strength comes from its convex arch shape, not flat thickness. The apex (highest point, over the stress area) bears the load. Structure: thin near cuticle (allows natural nail flex at proximal fold), thickest at apex, thinning again toward the tip (free edge should be thinned for a natural appearance). This three-zone structure maximizes durability while minimizing bulk." },
  { id: 291, question: "Which of the following is an appropriate home care recommendation for a client after a manicure service?", question_es: "¿Cuál de los siguientes es una recomendación apropiada de cuidado en el hogar para un cliente después de un servicio de manicura?", options: ["Apply cuticle oil daily (especially around the nail fold), wear gloves for household cleaning and dishwashing, avoid picking at the polish or cuticle, apply top coat every 2–3 days to refresh the manicure's protective seal", "Soak nails in hot water daily to keep them hydrated and prevent breakage", "Remove and reapply nail polish weekly using acetone to keep nails fresh — frequent changes improve nail health", "Avoid all hand lotion — moisturizing the skin will cause polish to lift faster"], options_es: ["Aplicar aceite de cutícula diariamente (especialmente alrededor del pliegue ungueal), usar guantes para la limpieza del hogar y lavar platos, evitar pellizcar el esmalte o la cutícula, aplicar top coat cada 2–3 días para refrescar el sello protector de la manicura", "Remojar las uñas en agua caliente diariamente para mantenerlas hidratadas y prevenir la rotura", "Eliminar y volver a aplicar el esmalte de uñas semanalmente usando acetona para mantener las uñas frescas — los cambios frecuentes mejoran la salud de las uñas", "Evitar toda loción de manos — hidratar la piel hará que el esmalte se levante más rápido"], correct: 0, explanation: "Post-manicure home care: (1) Daily cuticle oil — the single most effective nail health habit (hydrates cuticle and nail plate), (2) rubber gloves for wet work (water and cleaning chemicals are the most common causes of polish chipping and nail damage), (3) top coat refresh every 2–3 days (re-seals edges), (4) avoid tools as nail tips, (5) keep nails at a manageable length to prevent stress fractures." },
  { id: 292, question: "An esthetics client returns with chipped manicure polish after only two days and asks what caused the failure. The most likely causes include:", question_es: "Una cliente de estética regresa con el esmalte de manicura astillado después de solo dos días y pregunta qué causó el fallo. Las causas más probables incluyen:", options: ["Nails were not fully degreased before polish application (oil residue prevents adhesion), the service used soaking (wet nails expand/contract), polish layers were applied too thick, or the free edge was not wrapped — any of these alone or in combination causes premature chipping", "The polish quality is always defective when chipping occurs within 5 days — the product manufacturer is responsible", "Chipping always indicates nail fungal infection beneath the polish", "The client's diet caused the chipping — nutritional deficiencies always manifest as 2-day polish failure"], options_es: ["Las uñas no fueron completamente desengrasadas antes de la aplicación del esmalte (los residuos de aceite impiden la adherencia), el servicio usó remojo (las uñas húmedas se expanden/contraen), las capas de esmalte se aplicaron demasiado gruesas o el borde libre no fue envuelto — cualquiera de estos solos o en combinación causa astillamiento prematuro", "La calidad del esmalte siempre es defectuosa cuando ocurre astillamiento dentro de 5 días — el fabricante del producto es responsable", "El astillamiento siempre indica infección fúngica de las uñas debajo del esmalte", "La dieta del cliente causó el astillamiento — las deficiencias nutricionales siempre se manifiestan como fallo del esmalte de 2 días"], correct: 0, explanation: "Early polish failure (within 2–3 days) almost always indicates a technique or preparation problem: (1) oil on nail surface = most common (prevents adhesion), (2) wet nails from soaking = hydration cycle, (3) thick coats = uneven drying, surface dry but interior still liquid, (4) no free edge wrap = tip chipping, (5) no base coat = poor adhesion, (6) top coat applied before color dried = dragging, bubbling." },
  { id: 293, question: "Gel nails that are peeled off instead of properly soaked off cause:", question_es: "Las uñas de gel que se pelan en lugar de remojarse adecuadamente causan:", options: ["Significant damage to the natural nail plate — the gel bonds to the nail's surface layers, and forceful peeling removes those nail layers along with the gel, leaving the natural nail thin, rough, and prone to breakage", "No damage — peeling is a safe and effective removal method when the gel has grown out sufficiently", "Only cosmetic surface damage that resolves within 24 hours", "Fungal infection of the nail bed — peeling always introduces fungal organisms to the nail"], options_es: ["Daño significativo a la placa ungueal natural — el gel se une a las capas superficiales de la uña, y el pelado forzoso elimina esas capas de uña junto con el gel, dejando la uña natural delgada, rugosa y propensa a la rotura", "Sin daño — el pelado es un método de remoción seguro y efectivo cuando el gel ha crecido suficientemente", "Solo daño cosmético superficial que se resuelve dentro de las 24 horas", "Infección fúngica del lecho ungueal — el pelado siempre introduce organismos fúngicos en la uña"], correct: 0, explanation: "Gel products chemically bond to the nail plate's surface keratin layers during curing. When gel is peeled rather than chemically softened with acetone, it tears off the bonded nail surface layers with it — leaving the nail plate white, thin, rough, and weakened. This is called 'nail plate trauma' from mechanical gel removal. Multiple peeling sessions can thin nails to the point of pain and breakage." },
  { id: 294, question: "Post-pedicure foot care recommendations for a client with dry skin include:", question_es: "Las recomendaciones de cuidado de pies post-pedicura para un cliente con piel seca incluyen:", options: ["Applying a rich foot cream or lotion (containing urea 10–20%, shea butter, or glycerin) nightly before bed and covering with cotton socks — the occlusion from socks dramatically increases cream penetration and moisture retention for dry feet and heels", "Soaking feet in hot water for 30 minutes every evening — daily soaking is the best moisturizing strategy for dry feet", "Applying antiperspirant to the soles — this prevents the sweating that causes dryness", "Avoiding all foot creams — natural sebum production alone should keep feet moisturized"], options_es: ["Aplicar una crema o loción de pies rica (que contenga urea 10–20%, manteca de karité o glicerina) por la noche antes de acostarse y cubrir con calcetines de algodón — la oclusión de los calcetines aumenta dramáticamente la penetración de la crema y la retención de humedad para pies y talones secos", "Remojar los pies en agua caliente durante 30 minutos cada noche — el remojo diario es la mejor estrategia de hidratación para los pies secos", "Aplicar antitranspirante en las plantas — esto previene el sudor que causa la sequedad", "Evitar todas las cremas de pies — la producción natural de sebo solo debería mantener los pies hidratados"], correct: 0, explanation: "Nightly foot moisturization protocol: apply emollient-rich foot cream (urea is particularly effective — it is a humectant AND keratolytic, softening callus while attracting moisture), then cover with cotton socks overnight. The socks prevent evaporation of both the cream and foot moisture — dramatically increasing the treatment's effectiveness. This is the gold-standard home care recommendation for dry, calloused feet." },
  { id: 295, question: "A nail esthetician in Texas is permitted to use which of the following implements for callus reduction during a pedicure?", question_es: "Un esteticista de uñas en Texas tiene permiso para usar cuáles de los siguientes implementos para la reducción de callos durante una pedicura?", options: ["Non-motorized foot files, pumice stones, and similar abrasive tools for gentle surface callus reduction — implements that cut into living skin tissue (medical scalpel, rotary callus trimmers that penetrate deeply) may be outside esthetics scope and require physician licensure", "A scalpel or surgical blade — these are permitted tools in all Texas esthetics scope without restriction", "Motorized rotary callus removers at full speed — these are always within esthetics scope for all callus types", "None — callus reduction of any kind is prohibited in Texas esthetics scope and always requires podiatric referral"], options_es: ["Limas para pies no motorizadas, piedras pómez y herramientas abrasivas similares para la reducción suave de callos superficiales — los implementos que cortan en el tejido de piel viva (escalpelo médico, cortadores de callos rotativos que penetran profundamente) pueden estar fuera del alcance de la estética y requieren licencia médica", "Un escalpelo o hoja quirúrgica — estas son herramientas permitidas en todo el alcance de la estética de Texas sin restricciones", "Cortadores de callos rotativos motorizados a plena velocidad — estos siempre están dentro del alcance de la estética para todos los tipos de callos", "Ninguno — la reducción de callos de cualquier tipo está prohibida en el alcance de la estética de Texas y siempre requiere derivación podológica"], correct: 0, explanation: "Texas esthetics scope for callus work: foot files, pumice, and abrasive tools for surface reduction of non-living hyperkeratotic tissue are generally within scope. Medical-grade scalpel work (surgical callus shaving) that enters living tissue is outside esthetics scope — this is podiatric practice. Estheticians should work conservatively, never cutting into living tissue, and refer when the callus is deep, infected, or involves vascular compromise." },
  { id: 296, question: "To prevent the spread of fungal nail infections within an esthetics establishment performing pedicure services:", question_es: "Para prevenir la propagación de infecciones fúngicas de uñas dentro de un establecimiento de estética que realiza servicios de pedicura:", options: ["Decline service on nails with suspected onychomycosis, properly disinfect all pedicure equipment (basin, metal implements) between clients, use single-use files and buffers, and wear gloves when contact with potentially infected nail tissue occurs", "Only avoid touching the client's infected nails — the pedicure basin and other equipment pose no cross-contamination risk for fungal organisms", "Apply a thin coat of antifungal polish to the infected nails and proceed normally with service", "Soak all implements in water for 10 minutes between clients — water kills fungal organisms effectively"], options_es: ["Rechazar el servicio en uñas con sospecha de onicomicosis, desinfectar adecuadamente todo el equipo de pedicura (cubeta, implementos de metal) entre clientes, usar limas y buffers de uso único y usar guantes cuando ocurra contacto con tejido ungueal potencialmente infectado", "Solo evitar tocar las uñas infectadas del cliente — la cubeta de pedicura y otros equipos no presentan ningún riesgo de contaminación cruzada para los organismos fúngicos", "Aplicar una capa delgada de esmalte antimicótico en las uñas infectadas y proceder normalmente con el servicio", "Remojar todos los implementos en agua durante 10 minutos entre clientes — el agua mata los organismos fúngicos de manera efectiva"], correct: 0, explanation: "Fungal prevention in pedicure: dermatophytes survive on implements, basin surfaces, and in water. Prevention: (1) decline service for suspected onychomycosis (filing infected nails produces infectious dust), (2) thorough equipment disinfection between clients with antifungal-active EPA-registered products, (3) single-use files/buffers (cannot disinfect porous items), (4) gloves for contact with infected tissue, (5) complete drainage and disinfection of pedicure basins." },
  { id: 297, question: "A pedicure service performed on a client with varicose veins should include the modification of:", question_es: "Un servicio de pedicura realizado en un cliente con várices debe incluir la modificación de:", options: ["Avoiding deep pressure massage directly over varicose veins — massage over varicose veins can cause pain, damage the already-weakened vein walls, and potentially dislodge a thrombus; light, gentle massage movements around (not directly on) varicose veins are appropriate", "Avoiding all hot water soaks — clients with varicose veins cannot have any foot immersion", "Skipping all moisturizing steps — lotion aggravates varicose veins", "Refusing all pedicure services — varicose veins are an absolute contraindication for pedicure"], options_es: ["Evitar el masaje de presión profunda directamente sobre las várices — el masaje sobre las várices puede causar dolor, dañar las paredes venosas ya debilitadas y potencialmente desprender un trombo; los movimientos de masaje ligeros y suaves alrededor (no directamente sobre) las várices son apropiados", "Evitar todos los baños de agua caliente — los clientes con várices no pueden tener inmersión de pies", "Omitir todos los pasos de hidratación — la loción agrava las várices", "Rechazar todos los servicios de pedicura — las várices son una contraindicación absoluta para la pedicura"], correct: 0, explanation: "Varicose veins are dilated, weakened superficial veins with damaged valves. For pedicure services: (1) avoid direct deep massage over varicose veins (risk of thrombus dislodgement, pain, vein wall damage), (2) avoid very hot water soaks (heat dilates veins further), (3) avoid very long foot soaks. Gentle massage around (not over) varicose veins is acceptable. Standard nail care, gentle moisturization, and polish application are fine." },
  { id: 298, question: "Which step of a basic pedicure service is performed to smooth the heel and reduce surface callus?", question_es: "¿Qué paso de un servicio básico de pedicura se realiza para alisar el talón y reducir el callo superficial?", options: ["After the foot soak has softened the skin — using a foot file, pumice stone, or callus paddle on the heel and ball of the foot in smooth strokes to reduce the thickened hyperkeratotic tissue while the skin is still slightly damp and soft", "Before soaking — the foot file works best on dry, hard callus tissue for maximum abrasion", "After polish application — the foot file is used as the final finishing step", "Callus reduction is performed only if the client specifically requests it — it is never a standard pedicure step"], options_es: ["Después de que el baño de pies haya suavizado la piel — usando una lima para pies, piedra pómez o paleta de callos en el talón y la planta del pie con movimientos suaves para reducir el tejido hiperqueratósico engrosado mientras la piel todavía está ligeramente húmeda y suave", "Antes del remojo — la lima para pies funciona mejor en el tejido de callo seco y duro para una abrasión máxima", "Después de la aplicación del esmalte — la lima para pies se usa como el paso final de acabado", "La reducción de callos solo se realiza si el cliente lo solicita específicamente — nunca es un paso estándar de pedicura"], correct: 0, explanation: "Callus reduction sequence in pedicure: foot soak softens the hyperkeratotic tissue (making it much easier and safer to reduce), then while the skin is still damp/soft, use a foot file or pumice to smooth the heel and ball. Work with firm but controlled strokes. After callus reduction, rinse and pat dry, then proceed to cuticle care and nail service. Dry callus is harder to reduce and requires more aggressive action." },
  { id: 299, question: "The nail fold area (proximal and lateral nail folds) is particularly susceptible to infection during nail services because:", question_es: "El área del pliegue ungueal (pliegues ungueales proximales y laterales) es particularmente susceptible a la infección durante los servicios de uñas porque:", options: ["The nail fold skin is thin, fragile, and frequently manipulated during services — any disruption of the cuticle seal (cutting, aggressive pushing) removes the natural barrier protecting the matrix from bacterial and fungal entry, creating infection risk", "The nail fold is completely covered and protected by the nail plate — it never contacts implements during service", "Nail fold infections only occur from systemic diseases — service-related nail fold infections are extremely rare", "The nail fold's thick skin makes it resistant to infection from nail service manipulation"], options_es: ["La piel del pliegue ungueal es delgada, frágil y frecuentemente manipulada durante los servicios — cualquier interrupción del sello de la cutícula (corte, empuje agresivo) elimina la barrera natural que protege la matriz de la entrada bacteriana y fúngica, creando riesgo de infección", "El pliegue ungueal está completamente cubierto y protegido por la placa ungueal — nunca entra en contacto con los implementos durante el servicio", "Las infecciones del pliegue ungueal solo ocurren por enfermedades sistémicas — las infecciones del pliegue ungueal relacionadas con el servicio son extremadamente raras", "La piel gruesa del pliegue ungueal lo hace resistente a la infección por manipulación del servicio de uñas"], correct: 0, explanation: "The nail fold (periungual tissue) is the boundary between nail and skin. The cuticle seals this junction. When cuticle is cut or aggressively manipulated: the seal is broken, creating an entry point for bacteria (especially Staphylococcus aureus, Streptococcus) and fungi (especially Candida). Result: paronychia. Technique that preserves the cuticle seal — gentle pushing only, never cutting living cuticle — is the primary prevention." },
  { id: 300, question: "Nail care for clients undergoing chemotherapy may include which considerations?", question_es: "El cuidado de uñas para clientes sometidos a quimioterapia puede incluir cuáles consideraciones?", options: ["Nails may become brittle, discolored, develop Beau's lines, or separate from the nail bed (onycholysis) during chemotherapy — very gentle techniques are essential, infection control is critical (immunosuppression), and the esthetician should confirm with the client's oncologist that nail services are appropriate", "Chemotherapy has no documented effect on nail appearance or nail care protocols", "Chemotherapy clients must avoid all nail care services until one year after completing treatment", "Aggressive filing and buffing improve nail appearance for chemotherapy clients better than gentle techniques"], options_es: ["Las uñas pueden volverse quebradizas, decoloradas, desarrollar líneas de Beau o separarse del lecho ungueal (onicólisis) durante la quimioterapia — las técnicas muy suaves son esenciales, el control de infecciones es crítico (inmunosupresión) y el esteticista debe confirmar con el oncólogo del cliente que los servicios de uñas son apropiados", "La quimioterapia no tiene ningún efecto documentado en la apariencia de las uñas o los protocolos de cuidado de uñas", "Los clientes de quimioterapia deben evitar todos los servicios de cuidado de uñas hasta un año después de completar el tratamiento", "El limado y pulido agresivos mejoran la apariencia de las uñas para los clientes de quimioterapia mejor que las técnicas suaves"], correct: 0, explanation: "Chemotherapy-related nail changes: Beau's lines (matrix disruption during treatment cycles), onycholysis (especially with taxane drugs), nail discoloration, brittleness, and increased infection risk from immunosuppression. Service modifications: very gentle technique (no aggressive cuticle work, minimal pressure), strict infection control (gloves, fresh implements), physician/oncologist clearance recommended, and avoiding nail enhancements that could trap bacteria/fungi under an immunocompromised nail." },
]

let out = readFileSync(FILE, 'utf8')
out += Q.map(q => fmt(q)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${Q.length} Nail Care (ids ${Q[0].id}–${Q[Q.length-1].id})`)
